class Solution {
public:
    bool isValid(string s) {
        stack<char> openings;
        for (char bracket : s) {
            if (bracket == '(' || bracket == '[' || bracket == '{') {
                openings.push(bracket);
            } else {
                if (openings.empty()) return false;
                char opening = openings.top();
                openings.pop();
                if ((bracket == ')' && opening != '(') ||
                    (bracket == ']' && opening != '[') ||
                    (bracket == '}' && opening != '{')) return false;
            }
        }
        return openings.empty();
    }
};

