class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> result;
        vector<int> current;
        function<void(int)> build = [&](int index) {
            if (index == static_cast<int>(nums.size())) {
                result.push_back(current);
                return;
            }
            build(index + 1);
            current.push_back(nums[index]);
            build(index + 1);
            current.pop_back();
        };
        build(0);
        return result;
    }
};

