class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> seen;
        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            auto match = seen.find(target - nums[i]);
            if (match != seen.end()) return {match->second, i};
            seen[nums[i]] = i;
        }
        return {};
    }
};

